schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/north-star-metric.json",
  "title": "North Star Metric decision record",
  "type": "object",
  "required": ["product_name", "decided_on", "candidates", "chosen_nsm", "definition", "validation", "runner_ups", "input_metrics", "gaming_risks", "change_control"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "score": {"type": "integer", "minimum": 1, "maximum": 5},
    "rate": {"type": "number", "minimum": 0, "maximum": 1},
    "event_name": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "product_name": {"type": "string", "minLength": 2},
    "decided_on": {"$ref": "#/definitions/date"},
    "candidates": {
      "type": "array",
      "minItems": 3,
      "items": {
        "type": "object",
        "required": ["name", "counts", "scores", "total"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 3},
          "counts": {"type": "string", "enum": ["value_event", "revenue", "signups", "registered_users", "pageviews", "sessions", "mau"]},
          "scores": {
            "type": "object",
            "required": ["customer_value", "leading_indicator_of_revenue", "actionable_within_quarter", "understandable_without_data_team", "measurable_today"],
            "additionalProperties": false,
            "properties": {
              "customer_value": {"$ref": "#/definitions/score"},
              "leading_indicator_of_revenue": {"$ref": "#/definitions/score"},
              "actionable_within_quarter": {"$ref": "#/definitions/score"},
              "understandable_without_data_team": {"$ref": "#/definitions/score"},
              "measurable_today": {"$ref": "#/definitions/score"}
            }
          },
          "total": {"type": "integer", "minimum": 5, "maximum": 25}
        }
      }
    },
    "chosen_nsm": {
      "type": "object",
      "required": ["name", "is_highest_scoring"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "minLength": 3},
        "is_highest_scoring": {"type": "boolean"},
        "not_highest_because": {"type": "string", "minLength": 20}
      },
      "if": {"properties": {"is_highest_scoring": {"const": false}}},
      "then": {"required": ["not_highest_because"]}
    },
    "definition": {
      "type": "object",
      "required": ["events", "unit", "window", "threshold", "inclusions", "exclusions", "dashboard_url"],
      "additionalProperties": false,
      "properties": {
        "events": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/definitions/event_name"}},
        "unit": {"type": "string", "enum": ["users", "accounts", "teams", "transactions"]},
        "window": {"type": "string", "enum": ["daily", "weekly", "28_day"]},
        "threshold": {"type": "number", "exclusiveMinimum": 0},
        "inclusions": {"type": "array", "items": {"type": "string", "minLength": 3}},
        "exclusions": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 3}},
        "dashboard_url": {"type": "string", "pattern": "^https?://"}
      }
    },
    "validation": {
      "type": "object",
      "required": ["method", "cohort_size", "period_start", "period_end", "outcome", "rate_above", "rate_below", "delta", "result", "run_date"],
      "additionalProperties": false,
      "properties": {
        "method": {"const": "above_vs_below_threshold_cohort"},
        "cohort_size": {"type": "integer", "minimum": 1},
        "period_start": {"$ref": "#/definitions/date"},
        "period_end": {"$ref": "#/definitions/date"},
        "outcome": {"type": "string", "enum": ["retained", "converted_to_paid"]},
        "rate_above": {"$ref": "#/definitions/rate"},
        "rate_below": {"$ref": "#/definitions/rate"},
        "delta": {"type": "number", "exclusiveMinimum": 0, "maximum": 1},
        "result": {"type": "string", "enum": ["yes", "no", "inconclusive"]},
        "run_date": {"$ref": "#/definitions/date"}
      }
    },
    "runner_ups": {
      "type": "array",
      "minItems": 2,
      "items": {
        "type": "object",
        "required": ["name", "disposition"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 3},
          "disposition": {"type": "string", "enum": ["input_metric", "rejected"]},
          "rejection_reason": {"type": "string", "minLength": 20}
        },
        "if": {"properties": {"disposition": {"const": "rejected"}}},
        "then": {"required": ["rejection_reason"]}
      }
    },
    "input_metrics": {
      "type": "array",
      "minItems": 3,
      "maxItems": 5,
      "items": {
        "type": "object",
        "required": ["name", "dimension", "owning_team", "current_value", "target", "movable_within_quarter"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 3},
          "dimension": {"type": "string", "enum": ["breadth", "depth", "frequency", "efficiency"]},
          "owning_team": {"type": "string", "minLength": 2},
          "current_value": {"type": "number"},
          "target": {"type": "number"},
          "movable_within_quarter": {"const": true}
        }
      }
    },
    "gaming_risks": {
      "type": "object",
      "required": ["vectors", "inflatable_by_spend_alone"],
      "additionalProperties": false,
      "properties": {
        "vectors": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["vector", "guard"],
            "additionalProperties": false,
            "properties": {
              "vector": {"type": "string", "enum": ["paid_signups", "notification_spam", "internal_or_bot_activity", "threshold_lowering", "other"]},
              "guard": {
                "type": "object",
                "required": ["kind", "detail"],
                "additionalProperties": false,
                "properties": {
                  "kind": {"type": "string", "enum": ["definition_exclusion", "paired_quality_metric", "paired_retention_metric", "threshold_review_rule"]},
                  "detail": {"type": "string", "minLength": 10}
                }
              }
            }
          }
        },
        "inflatable_by_spend_alone": {"const": false}
      }
    },
    "change_control": {
      "type": "object",
      "required": ["previous_record", "series_break_date", "next_review_date"],
      "additionalProperties": false,
      "properties": {
        "previous_record": {"type": ["string", "null"], "minLength": 3},
        "series_break_date": {"anyOf": [{"type": "null"}, {"$ref": "#/definitions/date"}]},
        "next_review_date": {"$ref": "#/definitions/date"}
      },
      "if": {"properties": {"previous_record": {"type": "string"}}},
      "then": {"properties": {"series_break_date": {"type": "string"}}}
    }
  }
}

example.code:
{
  "product_name": "Trellis",
  "decided_on": "2026-07-20",
  "candidates": [
    {"name": "weekly teams completing at least one project", "counts": "value_event", "scores": {"customer_value": 5, "leading_indicator_of_revenue": 5, "actionable_within_quarter": 4, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 24},
    {"name": "weekly active teams", "counts": "mau", "scores": {"customer_value": 3, "leading_indicator_of_revenue": 3, "actionable_within_quarter": 4, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 20},
    {"name": "weekly signups", "counts": "signups", "scores": {"customer_value": 1, "leading_indicator_of_revenue": 2, "actionable_within_quarter": 5, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 18},
    {"name": "MRR", "counts": "revenue", "scores": {"customer_value": 2, "leading_indicator_of_revenue": 1, "actionable_within_quarter": 2, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 15}
  ],
  "chosen_nsm": {"name": "weekly teams completing at least one project", "is_highest_scoring": true},
  "definition": {
    "events": ["project_completed"],
    "unit": "teams",
    "window": "weekly",
    "threshold": 1,
    "inclusions": ["free and paid workspaces", "projects with at least two members"],
    "exclusions": ["internal workspaces (domain trellis.example)", "test data flagged is_test", "workspaces created in the current week"],
    "dashboard_url": "https://analytics.example.com/dashboards/nsm-weekly-completing-teams"
  },
  "validation": {
    "method": "above_vs_below_threshold_cohort",
    "cohort_size": 4200,
    "period_start": "2026-05-01",
    "period_end": "2026-06-30",
    "outcome": "retained",
    "rate_above": 0.62,
    "rate_below": 0.21,
    "delta": 0.41,
    "result": "yes",
    "run_date": "2026-07-15"
  },
  "runner_ups": [
    {"name": "weekly active teams", "disposition": "input_metric"},
    {"name": "weekly signups", "disposition": "rejected", "rejection_reason": "can be bought with acquisition spend and says nothing about value received; loses on customer value and leading indicator"},
    {"name": "MRR", "disposition": "rejected", "rejection_reason": "lags value by months and is moved by pricing and packaging rather than by the product; kept as the outcome the NSM is validated against"}
  ],
  "input_metrics": [
    {"name": "weekly active teams", "dimension": "breadth", "owning_team": "growth", "current_value": 310, "target": 400, "movable_within_quarter": true},
    {"name": "projects completed per active team", "dimension": "depth", "owning_team": "product", "current_value": 1.8, "target": 2.5, "movable_within_quarter": true},
    {"name": "share of teams active on 3 or more days a week", "dimension": "frequency", "owning_team": "lifecycle", "current_value": 0.44, "target": 0.55, "movable_within_quarter": true},
    {"name": "median days from workspace creation to first completed project", "dimension": "efficiency", "owning_team": "onboarding", "current_value": 4.2, "target": 2.5, "movable_within_quarter": true}
  ],
  "gaming_risks": {
    "vectors": [
      {"vector": "notification_spam", "guard": {"kind": "paired_retention_metric", "detail": "week-8 team retention is reported next to the NSM; a rising NSM with flat retention triggers a review"}},
      {"vector": "internal_or_bot_activity", "guard": {"kind": "definition_exclusion", "detail": "internal workspaces and is_test data are excluded in the definition; projects completed by integration bots do not count"}},
      {"vector": "threshold_lowering", "guard": {"kind": "threshold_review_rule", "detail": "the threshold of one completed project changes only through a new decision record with a series-break date"}}
    ],
    "inflatable_by_spend_alone": false
  },
  "change_control": {"previous_record": null, "series_break_date": null, "next_review_date": "2027-07-15"}
}

{
  "product_name": "Trellis",
  "decided_on": "2026-07-20",
  "candidates": [
    {"name": "MRR", "counts": "revenue", "scores": {"customer_value": 2, "leading_indicator_of_revenue": 1, "actionable_within_quarter": 2, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 22},
    {"name": "weekly signups", "counts": "signups", "scores": {"customer_value": 1, "leading_indicator_of_revenue": 2, "actionable_within_quarter": 5, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 18}
  ],
  "chosen_nsm": {"name": "MRR", "is_highest_scoring": false},
  "definition": {
    "events": [],
    "unit": "dollars",
    "window": "monthly",
    "threshold": 0,
    "inclusions": [],
    "exclusions": [],
    "dashboard_url": "see finance"
  },
  "validation": {
    "method": "correlates_with_retention",
    "cohort_size": 0,
    "period_start": "2026-05-01",
    "period_end": "2026-06-30",
    "outcome": "retained",
    "rate_above": 0.5,
    "rate_below": 0.5,
    "delta": 0,
    "result": "inconclusive",
    "run_date": "2026-07-15"
  },
  "runner_ups": [
    {"name": "weekly signups", "disposition": "secondary_nsm"}
  ],
  "input_metrics": [
    {"name": "grow MRR", "dimension": "revenue", "owning_team": "everyone", "current_value": 120000, "target": 200000, "movable_within_quarter": false}
  ],
